CREATE COLUMN TABLE "TEST_AP"."AACS" ("Code" NVARCHAR(20) NOT NULL , "Name" NVARCHAR(100), "AssetType" NVARCHAR(1) DEFAULT 'G', "LimitFrom" DECIMAL(21,6) CS_FIXED, "LimitTo" DECIMAL(21,6) CS_FIXED, "DataSource" NVARCHAR(1) DEFAULT 'N', "UserSign" SMALLINT CS_INT, "LogInstanc" INTEGER CS_INT DEFAULT 0 NOT NULL , "CreateDate" LONGDATE CS_LONGDATE, "UserSign2" SMALLINT CS_INT, "UpdateDate" LONGDATE CS_LONGDATE, "BPLId" INTEGER CS_INT, "AttrGrp" INTEGER CS_INT DEFAULT -1, "SnapshotId" INTEGER CS_INT DEFAULT 0, PRIMARY KEY ("Code", "LogInstanc")) UNLOAD PRIORITY 5  AUTO MERGE 